    <Autocomplete
      items={results}
      filter={null}
      value={query}
      onValueChange={(query) => {
        const next = { query };
        setRequest(next);
        if (!query) setResponse({ request: next, results: [] });
      }}
      itemToStringValue={(movie) => movie.title}
    >
      <AutocompleteInput aria-label="Search movies" placeholder="Search title or year…" />
