  playgroundColumnHelper.accessor("item", { header: "Item" }),
  playgroundColumnHelper.accessor("value", { header: "Value" }),
]);

export function PlaygroundTable({ rows, caption }: PlaygroundArgs) {
  const data = Array.from({ length: rows }, (_, index) => ({
    item: `Item ${index + 1}`,
    value: index + 1,
